def fusionner(intervalles):
    if not intervalles:
        return []
    sorted_intervals = sorted(intervalles, key=lambda x: (x[0], x[1]))
    merged = []
    for debut, fin in sorted_intervals:
        if merged and debut <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], fin))
        else:
            merged.append((debut, fin))
    return merged
